add('share-sweets',0,T('Разделить конфеты поровну','Поділити цукерки порівну','Share sweets equally'),T('Поровну означает одинаковое целое количество каждому. Неделимый остаток сохраняем отдельно.','Порівну означає однакову цілу кількість кожному. Неподільну остачу зберігаємо окремо.','Everyone gets the same whole number of sweets. Keep leftovers separate.'),[T('Прочитай `sweets` от 0 до 100, затем `people` от 1 до 10. Обе строки есть всегда.','Зчитай `sweets` від 0 до 100, потім `people` від 1 до 10. Обидва рядки є завжди.','Read `sweets` from 0 to 100, then `people` from 1 to 10. Both input lines are present.'),T('Найди количество конфет каждому и количество оставшихся конфет. Разделитель — число people, а не постоянное число из примера.','Знайди кількість цукерок кожному та кількість цукерок, що залишилися. Дільник — число people, а не стала з прикладу.','Find each person’s share and the leftover sweets. Divide by people, not by a fixed example number.'),T('Выведи два целых числа на одной строке: долю каждого, затем остаток. Людей может быть больше, чем конфет.','Виведи два цілі числа в одному рядку: частку кожного, потім остачу. Людей може бути більше, ніж цукерок.','Print two integers on one line: each person’s share, then the remainder. There may be more people than sweets.')],T('Две строки: количество конфет, затем людей.','Два рядки: кількість цукерок, потім людей.','Two lines: sweets, then people.'),'sweets = int(input())\npeople = int(input())\n\n',[[['16','5'],'3 1'],[['0','4'],'0 0'],[['3','7'],'0 3'],[['18','3'],'6 0'],[['9','1'],'9 0'],[['100','9'],'11 1']],[T('Каждый получает только полные конфеты: нужен целый результат деления.','Кожен отримує лише цілі цукерки: потрібен цілий результат ділення.','Each person gets whole sweets, so use the whole part of division.'),T('Остаток всегда меньше числа людей. Проверь пример, где конфет меньше, чем людей.','Остача завжди менша за кількість людей. Перевір приклад, де цукерок менше, ніж людей.','The remainder is smaller than the number of people. Try fewer sweets than people.'),T('Посчитай оба значения на основе тех же sweets и people, затем выведи их вместе.','Обчисли обидва значення з тих самих sweets та people, потім виведи разом.','Calculate both values from the same sweets and people, then print them together.')]);
add('command-word',1,T('Команда с лишними пробелами','Команда із зайвими пробілами','A command with extra spaces'),T('Человек может написать START или добавить пробелы. Подготовим текст до проверки.','Людина може написати START або додати пробіли. Підготуємо текст перед перевіркою.','Someone may type START or add spaces. Prepare the text before comparing it.'),[T('Прочитай строку `command`. Команды start и stop пишутся латиницей.','Зчитай рядок `command`. Команди start та stop пишуться латиницею.','Read `command`. The command words start and stop use Latin letters.'),T('Убери пробелы по краям через `.strip()` и переведи буквы в маленькие через `.lower()`. Сохрани обработанный текст.','Прибери пробіли по краях через `.strip()` і переведи літери в малі через `.lower()`. Збережи оброблений текст.','Remove edge whitespace with `.strip()`, lowercase with `.lower()`, and store the prepared text.'),T('После обработки start → «Старт», stop → «Остановка», любой другой текст → «Неизвестная команда». Пустой текст тоже неизвестный.','Після обробки start → «Старт», stop → «Зупинка», будь-який інший текст → «Невідома команда». Порожній текст теж невідомий.','After preparation: start → “Start”, stop → “Stop”, any other text → “Unknown command”. Empty text is unknown too.')],T('Одна строка текста, иногда с пробелами и большими буквами.','Один рядок тексту, іноді з пробілами й великими літерами.','One text line, possibly with spaces and capitals.'),'command = input()\n\n',[[['  START  '],T('Старт','Старт','Start')],[['Stop'],T('Остановка','Зупинка','Stop')],[['start'],T('Старт','Старт','Start')],[['  stop'],T('Остановка','Зупинка','Stop')],[['hello'],T('Неизвестная команда','Невідома команда','Unknown command')],[['   '],T('Неизвестная команда','Невідома команда','Unknown command')],[['st art'],T('Неизвестная команда','Невідома команда','Unknown command')]],[T('Сначала обработай текст, потом сравнивай. До обработки START отличается от start.','Спершу оброби текст, потім порівнюй. До обробки START відрізняється від start.','Prepare first, compare second. Before preparation, START differs from start.'),T('strip() убирает пробелы по краям, но не внутри: st art не станет start.','strip() прибирає пробіли по краях, але не всередині: st art не стане start.','strip() removes edge whitespace, not internal spaces: st art does not become start.'),T('Обе операции возвращают новый текст. Сохрани результат в переменную, которую будешь проверять.','Обидві операції повертають новий текст. Збережи результат у змінну, яку перевірятимеш.','Both operations return new text. Store it in the variable you compare.')]);
add('clean-coupon',1,T('Купон в любом регистре','Купон у будь-якому регістрі','A case-insensitive coupon'),T('Нужный купон можно узнать даже после ввода Vip или VIP с пробелами.','Потрібний купон можна впізнати навіть після вводу Vip або VIP із пробілами.','Recognize the coupon even when entered as Vip or VIP with spaces.'),[T('Прочитай `coupon`. Убери пробелы по краям и переведи текст в маленькие буквы.','Зчитай `coupon`. Прибери пробіли по краях і переведи текст у малі літери.','Read `coupon`, strip edge whitespace, and lowercase it.'),T('Обработанный текст vip даёт скидку 20. Любой другой текст, включая пустой, даёт 0. Выведи только число скидки.','Оброблений текст vip дає знижку 20. Будь-який інший текст, включно з порожнім, дає 0. Виведи лише число знижки.','Prepared text vip gives a discount of 20. Anything else, including empty text, gives 0. Print only the discount number.')],T('Одна строка: купон латиницей или другой текст.','Один рядок: купон латиницею або інший текст.','One line: a Latin-letter coupon or other text.'),'coupon = input()\n\n',[[['VIP'],'20'],[['  Vip  '],'20'],[['vip'],'20'],[['vIp'],'20'],[['ordinary'],'0'],[['   '],'0'],[['v ip'],'0']],[T('После lower() проверяем маленькое слово vip.','Після lower() перевіряємо мале слово vip.','After lower(), compare with lowercase vip.'),T('Вычислять стоимость покупки не требуется: ответ — 20 или 0.','Обчислювати вартість покупки не потрібно: відповідь — 20 або 0.','No purchase-price calculation is needed: the answer is 20 or 0.'),T('Результат обработки надо сохранить. Сама команда coupon.lower() без присваивания не заменит coupon.','Результат обробки треба зберегти. Сама команда coupon.lower() без присвоєння не замінить coupon.','Store the prepared text. Calling coupon.lower() without assignment does not replace coupon.')]);
add('club-flag',2,T('Можно ли участвовать?','Чи можна брати участь?','Is participation allowed?'),T('Сохраним ответ условия как True или False, а не как текст в кавычках.','Збережімо відповідь умови як True або False, а не як текст у лапках.','Store a condition’s True or False result, rather than quoted text.'),[T('Прочитай `age` от 0 до 120, затем `invite` («да» или «нет»). Обе строки есть всегда.','Зчитай `age` від 0 до 120, потім `invite` («так» або «ні»). Обидва рядки є завжди.','Read `age` from 0 to 120, then `invite` (“yes” or “no”). Both lines are present.'),T('Участие разрешено, если возраст от 16 включительно и invite равен «да». Нужны обе проверки: используй and. Сохрани ответ в `allowed`.','Участь дозволено, якщо вік від 16 включно й invite дорівнює «так». Потрібні обидві перевірки: використай and. Збережи відповідь у `allowed`.','Participation requires age 16 or more and invite equal to “yes”. Both checks must pass: use and. Store the result in `allowed`.'),T('Выведи allowed. Python сам печатает логические значения как True или False. Эти слова не переводятся и пишутся с большой первой буквы.','Виведи allowed. Python сам друкує логічні значення як True або False. Ці слова не перекладаються й пишуться з великої першої літери.','Print allowed. Python prints Boolean values as True or False. These words are not translated and begin with a capital letter.')],T('Две строки: возраст, затем ответ о приглашении.','Два рядки: вік, потім відповідь про запрошення.','Two lines: age, then the invitation answer.'),'age = int(input())\ninvite = input()\n\n',[[['16',T('да','так','yes')],'True'],[['15',T('да','так','yes')],'False'],[['20',T('нет','ні','no')],'False'],[['16',T('нет','ні','no')],'False'],[['0',T('нет','ні','no')],'False'],[['120',T('да','так','yes')],'True']],[T('16 подходит: «от 16 включительно» допускает равенство.','16 підходить: «від 16 включно» допускає рівність.','16 qualifies: “16 or more” includes equality.'),T('Ответ сравнения можно сохранить: например, enough = points >= 10. Это не число points, а ответ на вопрос.','Відповідь порівняння можна зберегти: наприклад, enough = points >= 10. Це не число points, а відповідь на запитання.','Store a comparison result, for example enough = points >= 10. It is an answer to a question, not the points number.'),T('Если хотя бы одна проверка с and неверна, весь ответ False. Кавычки вокруг условия превратят его в текст.','Якщо хоча б одна перевірка з and хибна, вся відповідь False. Лапки навколо умови перетворять її на текст.','If either and check fails, the result is False. Putting the condition in quotes makes it text.')]);
add('connection',2,T('Есть ли связь?','Чи є зв’язок?','Is there a connection?'),T('Достаточно одного доступного соединения. Отрицание not пригодится для отсутствия связи.','Достатньо одного доступного з’єднання. Заперечення not знадобиться для відсутності зв’язку.','One available connection is enough. Use not to describe being offline.'),[T('Прочитай две строки `wifi` и `cable`. Каждая содержит «да» или «нет».','Зчитай два рядки `wifi` та `cable`. Кожен містить «так» або «ні».','Read `wifi` and `cable`, each containing “yes” or “no”.'),T('Сохрани в `online` ответ: доступен Wi-Fi или кабель? Достаточно хотя бы одного «да», поэтому проверки соединяются через or.','Збережи в `online` відповідь: доступний Wi-Fi або кабель? Достатньо хоча б одного «так», тому перевірки з’єднуються через or.','Store in `online` whether Wi-Fi or cable is available. Either “yes” is enough, so combine checks with or.'),T('Если not online, выведи «Офлайн», иначе «Онлайн». not меняет ответ проверки на противоположный.','Якщо not online, виведи «Офлайн», інакше «Онлайн». not змінює відповідь перевірки на протилежну.','If not online, print “Offline”; otherwise, “Online”. Not reverses a Boolean answer.')],T('Две строки: доступность Wi-Fi, затем кабеля.','Два рядки: доступність Wi-Fi, потім кабелю.','Two lines: Wi-Fi availability, then cable availability.'),'wifi = input()\ncable = input()\n\n',[[[T('да','так','yes'),T('нет','ні','no')],T('Онлайн','Онлайн','Online')],[[T('нет','ні','no'),T('да','так','yes')],T('Онлайн','Онлайн','Online')],[[T('да','так','yes'),T('да','так','yes')],T('Онлайн','Онлайн','Online')],[[T('нет','ні','no'),T('нет','ні','no')],T('Офлайн','Офлайн','Offline')]],[T('Не путай or с and: здесь одного соединения достаточно.','Не плутай or з and: тут одного з’єднання достатньо.','Use or rather than and: one connection is enough.'),T('В каждой проверке повтори сравнение: wifi == нужное_слово or cable == нужное_слово.','У кожній перевірці повтори порівняння: wifi == потрібне_слово or cable == потрібне_слово.','Write a complete comparison on each side: wifi == the_word or cable == the_word.'),T('При online = False выражение not online даёт True. Значит, ветка отсутствия связи выполняется.','Для online = False вираз not online дає True. Отже, виконується гілка відсутності зв’язку.','With online = False, not online is True, so the offline branch runs.')]);
add('delivery-price',3,T('Доставка и доплата','Доставка й доплата','Delivery and a surcharge'),T('Сначала выбираем стоимость доставки, затем отдельно учитываем дальний адрес.','Спершу обираємо вартість доставки, потім окремо враховуємо далеку адресу.','Choose a delivery fee first, then separately account for a remote address.'),[T('Прочитай целое `total` от 0 до 5000, затем `remote` («да» или «нет»). Обе строки есть всегда.','Зчитай ціле `total` від 0 до 5000, потім `remote` («так» або «ні»). Обидва рядки є завжди.','Read integer `total` from 0 to 5000, then `remote` (“yes” or “no”). Both lines are present.'),T('Базовая доставка: при сумме от 1000 включительно — 0, иначе — 150. Сохрани её в `fee`.','Базова доставка: для суми від 1000 включно — 0, інакше — 150. Збережи її у `fee`.','Base delivery is 0 for totals of at least 1000, otherwise 150. Store it in `fee`.'),T('Если remote равен «да», прибавь 80 к уже сохранённому fee. Это отдельная доплата: она добавляется даже к бесплатной базовой доставке.','Якщо remote дорівнює «так», додай 80 до вже збереженого fee. Це окрема доплата: вона додається навіть до безкоштовної базової доставки.','If remote equals “yes”, add 80 to the stored fee. This separate surcharge also applies when base delivery is free.'),T('После всех изменений выведи только итоговую стоимость доставки.','Після всіх змін виведи лише підсумкову вартість доставки.','After all updates, print only the final delivery fee.')],T('Две строки: сумма покупки, затем дальний ли адрес.','Два рядки: сума покупки, потім чи далека адреса.','Two lines: purchase total, then whether the address is remote.'),'total = int(input())\nremote = input()\n\n',[[['1000',T('нет','ні','no')],'0'],[['1000',T('да','так','yes')],'80'],[['999',T('да','так','yes')],'230'],[['999',T('нет','ні','no')],'150'],[['0',T('да','так','yes')],'230'],[['5000',T('да','так','yes')],'80']],[T('Сумма 1000 уже подходит для бесплатной базовой доставки.','Сума 1000 уже підходить для безкоштовної базової доставки.','A total of 1000 qualifies for free base delivery.'),T('После выбора fee проверка remote должна выполняться при любом базовом тарифе.','Після вибору fee перевірка remote має виконуватися за будь-якого базового тарифу.','Check remote after choosing fee, whichever base fee was selected.'),T('Пример изменения: value = value + 8 берёт старое value и сохраняет увеличенное. Итог печатай после проверки доплаты.','Приклад зміни: value = value + 8 бере старе value й зберігає збільшене. Підсумок друкуй після перевірки доплати.','For example, value = value + 8 stores an increase to the old value. Print after checking the surcharge.')]);
add('parking-final',3,T('Финал: стоимость стоянки','Фінал: вартість стоянки','Finale: parking cost'),T('Объедини деление на части, обработку текста и изменение результата.','Поєднай поділ на частини, обробку тексту та зміну результату.','Combine splitting into parts, preparing text, and updating a result.'),[T('Прочитай `minutes` от 0 до 180, затем строку `code`. Обе строки есть всегда, даже при нуле минут.','Зчитай `minutes` від 0 до 180, потім рядок `code`. Обидва рядки є завжди, навіть за нуля хвилин.','Read `minutes` from 0 to 180, then `code`. Both lines are present, including for zero minutes.'),T('Каждый полный час стоит 120. Найди полные часы через // и оставшиеся минуты через %. Сохрани стоимость полных часов в `price`.','Кожна повна година коштує 120. Знайди повні години через // та решту хвилин через %. Збережи вартість повних годин у `price`.','Each complete hour costs 120. Use // for whole hours and % for leftover minutes. Store the complete-hour cost in `price`.'),T('Если остались минуты после полных часов, прибавь к цене 40 один раз. Например, 75 минут — один полный час и 15 минут остатка, базовая цена 160.','Якщо залишилися хвилини після повних годин, додай до ціни 40 один раз. Наприклад, 75 хвилин — одна повна година та 15 хвилин остачі, базова ціна 160.','If minutes remain after full hours, add 40 once. For example, 75 minutes is one full hour plus 15 leftover minutes, so the base price is 160.'),T('Обработай code: убери пробелы по краям и переведи в маленькие буквы. Если получилось club и цена больше нуля, уменьши цену на 30. Иначе цена не меняется.','Оброби code: прибери пробіли по краях і переведи в малі літери. Якщо вийшло club і ціна більша за нуль, зменш ціну на 30. Інакше ціна не змінюється.','Strip and lowercase code. If it becomes club and the price is greater than zero, subtract 30; otherwise, leave the price unchanged.'),T('Один раз выведи окончательное число. При нуле минут результат 0 с любым кодом.','Один раз виведи остаточне число. За нуля хвилин результат 0 з будь-яким кодом.','Print the final number once. Zero minutes costs 0 with any code.')],T('Две строки: минуты, затем код или другой текст.','Два рядки: хвилини, потім код або інший текст.','Two lines: minutes, then a code or other text.'),'minutes = int(input())\ncode = input()\n\n',[[['75',' CLUB '],'130'],[['60','none'],'120'],[['0','club'],'0'],[['1','club'],'10'],[['59','none'],'40'],[['120','club'],'210'],[['121','none'],'280'],[['180','ClUb'],'330']],[T('Сначала посчитай базовую цену без кода. Остаток 0 означает, что доплата 40 не нужна.','Спершу обчисли базову ціну без коду. Остача 0 означає, що доплата 40 не потрібна.','Calculate the base price first. A zero remainder means no 40 surcharge.'),T('Скидка применяется к уже готовой базовой цене. Нужны обе проверки: нужный код и положительная цена.','Знижка застосовується до вже готової базової ціни. Потрібні обидві перевірки: потрібний код та додатна ціна.','Apply the discount to the calculated base price. Both checks must pass: the code matches and the price is positive.'),T('Для 0 минут код всё равно читается, но скидка пропускается. Для 75 минут с club итог: 120 + 40 − 30.','Для 0 хвилин код усе одно зчитується, але знижка пропускається. Для 75 хвилин із club підсумок: 120 + 40 − 30.','For zero minutes, still read the code but skip the discount. For 75 minutes with club, calculate 120 + 40 − 30.')]);
const extraTasks=[{"id":"full-packs","module":0,"title":["Только полные упаковки","Лише повні пакунки","Only full packs"],"intro":["Начнём с одной операции: найти количество полных групп. Остаток пока не нужен.","Почнімо з однієї операції: знайти кількість повних груп. Остача поки не потрібна.","Start with one operation: count complete groups. Ignore the remainder for now."],"requirements":[["Прочитай целое число `items` от 0 до 100. В одну упаковку входит 4 предмета.","Зчитай ціле число `items` від 0 до 100. В один пакунок вміщується 4 предмети.","Read integer `items` from 0 to 100. Each pack holds 4 items."],["Найди, сколько полных групп по 4 помещается в items. Оператор `//` делит и даёт целое количество полных групп. Сохрани результат в `packs`.","Знайди, скільки повних груп по 4 вміщується у items. Оператор `//` ділить і дає цілу кількість повних груп. Збережи результат у `packs`.","Find how many complete groups of 4 fit into items. The `//` operator gives the whole number of full groups. Store it in `packs`."],["Выведи только packs. Если предметов меньше 4, полных упаковок будет 0.","Виведи лише packs. Якщо предметів менше за 4, повних пакунків буде 0.","Print only packs. Fewer than 4 items means zero full packs."]],"input":["Одно число: сколько предметов.","Одне число: скільки предметів.","One number: item count."],"starter":"items = int(input())\n\n","cases":[{"input":["18"],"out":"4"},{"input":["4"],"out":"1"},{"input":["3"],"out":"0"},{"input":["0"],"out":"0"},{"input":["20"],"out":"5"},{"input":["100"],"out":"25"}],"hints":[["18 предметов — это четыре полные группы по 4. Два лишних предмета сейчас не считаем.","18 предметів — це чотири повні групи по 4. Два зайві предмети зараз не рахуємо.","18 items contain four full groups of 4. Ignore the two leftovers."],["Слева от // поставь общее количество, справа — размер одной группы.","Ліворуч від // постав загальну кількість, праворуч — розмір однієї групи.","Put the total on the left of // and the group size on the right."],["Вычисление использует items из ввода. После сохранения выведи новую переменную через print().","Обчислення використовує items із вводу. Після збереження виведи нову змінну через print().","Use items from the input. After storing the calculation, print the new variable."]],"time":"3–7","revision":1,"preparation":{"topic":"integer-parts","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"leftover-pieces","module":0,"title":["Только остаток","Лише остача","Only the remainder"],"intro":["Теперь другой вопрос: сколько предметов осталось после полных групп?","Тепер інше запитання: скільки предметів залишилося після повних груп?","Now ask a different question: how many items remain after full groups?"],"requirements":[["Прочитай `items` от 0 до 100. Размер одной группы снова равен 4.","Зчитай `items` від 0 до 100. Розмір однієї групи знову дорівнює 4.","Read `items` from 0 to 100. The group size is still 4."],["Сохрани в `left` остаток от деления items на 4. Для остатка используют `%`. Здесь не требуется количество полных групп.","Збережи у `left` остачу від ділення items на 4. Для остачі використовують `%`. Тут не потрібна кількість повних груп.","Store in `left` the remainder when items is divided by 4, using `%`. Do not count full groups here."],["Выведи только left. При делении без остатка ответ равен 0.","Виведи лише left. Для ділення без остачі відповідь дорівнює 0.","Print only left. Exact division leaves zero."]],"input":["Одно число: сколько предметов.","Одне число: скільки предметів.","One number: item count."],"starter":"items = int(input())\n\n","cases":[{"input":["18"],"out":"2"},{"input":["4"],"out":"0"},{"input":["3"],"out":"3"},{"input":["0"],"out":"0"},{"input":["21"],"out":"1"},{"input":["99"],"out":"3"}],"hints":[["В 18 помещается 16 предметов в полных группах. Остаётся 2.","З 18 у повних групах поміщається 16 предметів. Залишається 2.","Of 18 items, 16 fit into full groups. Two remain."],["// отвечает «сколько групп», а % — «сколько осталось». Сейчас нужен второй вопрос.","// відповідає «скільки груп», а % — «скільки залишилося». Зараз потрібне друге запитання.","// counts groups; % counts leftovers. You need the second answer."],["Остаток при делении на 4 может быть 0, 1, 2 или 3. Проверь на маленьком числе.","Остача від ділення на 4 може бути 0, 1, 2 або 3. Перевір на маленькому числі.","A remainder modulo 4 is 0, 1, 2 or 3. Try a small input."]],"time":"3–7","revision":1,"preparation":{"topic":"integer-parts","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"digit-parts","module":0,"title":["Десятки и единицы","Десятки й одиниці","Tens and ones"],"intro":["Закрепим две операции на знакомом числе: 47 — это 4 десятка и 7 единиц.","Закріпимо дві операції на знайомому числі: 47 — це 4 десятки й 7 одиниць.","Practise both operations: 47 has 4 tens and 7 ones."],"requirements":[["Прочитай целое `number` от 0 до 99. Один десяток содержит 10 единиц.","Зчитай ціле `number` від 0 до 99. Один десяток містить 10 одиниць.","Read integer `number` from 0 to 99. One ten contains 10 ones."],["Полные группы по 10 сохрани в `tens`, оставшиеся единицы — в `ones`. Используй // и %.","Повні групи по 10 збережи у `tens`, решту одиниць — у `ones`. Використай // та %.","Store complete groups of 10 in `tens` and the remainder in `ones`. Use // and %."],["Выведи tens и ones на одной строке через пробел. Число 7 должно дать 0 7.","Виведи tens та ones в одному рядку через пробіл. Число 7 має дати 0 7.","Print tens and ones on one line separated by a space. Input 7 gives 0 7."]],"input":["Одно целое число от 0 до 99.","Одне ціле число від 0 до 99.","One integer from 0 to 99."],"starter":"number = int(input())\n\n","cases":[{"input":["47"],"out":"4 7"},{"input":["7"],"out":"0 7"},{"input":["10"],"out":"1 0"},{"input":["0"],"out":"0 0"},{"input":["99"],"out":"9 9"},{"input":["50"],"out":"5 0"}],"hints":[["Для 47 сначала выдели четыре группы по 10. Остаток равен 7.","Для 47 спершу виділи чотири групи по 10. Остача дорівнює 7.","47 has four groups of 10 and a remainder of 7."],["Для обеих операций нужен один делитель — 10. Исходное number не меняется.","Для обох операцій потрібен один дільник — 10. Початкове number не змінюється.","Both operations use divisor 10. The original number stays unchanged."],["print() умеет выводить несколько переменных: перечисли их через запятую в нужном порядке.","print() уміє виводити кілька змінних: переліч їх через кому в потрібному порядку.","Print multiple variables by separating them with commas in the required order."]],"time":"3–7","revision":1,"preparation":{"topic":"integer-parts","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"boxes-needed","module":0,"title":["Коробка для остатка","Коробка для остачі","A box for leftovers"],"intro":["Соединим деление и знакомый if: даже один лишний предмет требует ещё одну коробку.","Поєднаймо ділення й знайомий if: навіть один зайвий предмет потребує ще одну коробку.","Combine division with a familiar if: even one leftover item needs another box."],"requirements":[["Прочитай `items` от 0 до 100, затем `capacity` от 1 до 10. Оба числа есть всегда.","Зчитай `items` від 0 до 100, потім `capacity` від 1 до 10. Обидва числа є завжди.","Read `items` from 0 to 100, then `capacity` from 1 to 10. Both inputs are present."],["Сначала сохрани количество полных коробок в `boxes` через //. Отдельно найди остаток через %.","Спершу збережи кількість повних коробок у `boxes` через //. Окремо знайди остачу через %.","First store the full-box count in `boxes` using //. Separately find the remainder using %."],["Если остаток больше 0, увеличь сохранённое boxes на 1. Иначе ничего не меняй. Выведи только итоговое количество коробок. При items = 0 ответ 0.","Якщо остача більша за 0, збільш збережене boxes на 1. Інакше нічого не змінюй. Виведи лише підсумкову кількість коробок. Для items = 0 відповідь 0.","If the remainder is greater than 0, increase the stored boxes by 1. Otherwise leave it unchanged. Print only the final box count. Zero items need zero boxes."]],"input":["Две строки: предметы и вместимость коробки.","Два рядки: предмети й місткість коробки.","Two lines: items and box capacity."],"starter":"items = int(input())\ncapacity = int(input())\n\n","cases":[{"input":["17","5"],"out":"4"},{"input":["15","5"],"out":"3"},{"input":["0","5"],"out":"0"},{"input":["1","5"],"out":"1"},{"input":["100","10"],"out":"10"},{"input":["10","3"],"out":"4"}],"hints":[["17 предметов занимают 3 полные коробки по 5 и ещё одну для двух оставшихся.","17 предметів займають 3 повні коробки по 5 і ще одну для двох решти.","17 items fill 3 boxes of 5, plus one box for the remaining two."],["Проверяй именно остаток: больше нуля означает, что нужна дополнительная коробка.","Перевіряй саме остачу: більше нуля означає, що потрібна додаткова коробка.","Test the remainder: a positive value means one extra box."],["Внутри if сохрани новое boxes: старое значение плюс 1. Итог печатай после if без отступа.","Усередині if збережи нове boxes: старе значення плюс 1. Підсумок друкуй після if без відступу.","Inside if, store the old boxes plus 1. Print after the if, without indentation."]],"time":"3–7","revision":1,"preparation":{"topic":"integer-parts","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"trim-message","module":1,"title":["Убрать пробелы по краям","Прибрати пробіли по краях","Remove edge spaces"],"intro":["Потренируем только strip(). Буквы и пробелы внутри пока не меняем.","Потренуймо лише strip(). Літери й пробіли всередині поки не змінюємо.","Practise strip() alone. Leave letters and internal spaces unchanged."],"requirements":[["Прочитай строку `message`.","Зчитай рядок `message`.","Read `message`."],["Примени к message операцию `.strip()` и сохрани её результат в `clean`. Она убирает пробелы только с начала и конца строки.","Застосуй до message операцію `.strip()` й збережи її результат у `clean`. Вона прибирає пробіли лише з початку й кінця рядка.","Apply `.strip()` to message and store its result in `clean`. It removes spaces at the start and end."],["Выведи clean. Не меняй регистр букв и не убирай пробелы между словами.","Виведи clean. Не змінюй регістр літер і не прибирай пробіли між словами.","Print clean. Preserve capital letters and spaces between words."]],"input":["Одна строка текста.","Один рядок тексту.","One text line."],"starter":"message = input()\n\n","cases":[{"input":["  Hello  "],"out":"Hello"},{"input":["word"],"out":"word"},{"input":["  TWO WORDS "],"out":"TWO WORDS"},{"input":[" x"],"out":"x"},{"input":["x "],"out":"x"},{"input":["   "],"out":""}],"hints":[["«  Hello  » превращается в «Hello». Большая H остаётся большой.","«  Hello  » перетворюється на «Hello». Велика H залишається великою.","“  Hello  ” becomes “Hello”. The capital H stays capital."],["Точка связывает операцию со строкой: имя_строки.strip(). Скобки запускают операцию.","Крапка пов’язує операцію з рядком: назва_рядка.strip(). Дужки запускають операцію.","Use string_name.strip(): the dot selects the operation and parentheses call it."],["Операция возвращает новый текст. Сохрани его через =, затем выведи сохранённое значение.","Операція повертає новий текст. Збережи його через =, потім виведи збережене значення.","The operation returns new text. Store it with =, then print the stored value."]],"time":"3–7","revision":1,"preparation":{"topic":"clean-text","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"lowercase-message","module":1,"title":["Буквы в нижнем регистре","Літери в нижньому регістрі","Lowercase letters"],"intro":["Теперь только lower(): большие буквы превращаются в маленькие.","Тепер лише lower(): великі літери перетворюються на малі.","Now practise lower() alone: capitals become lowercase."],"requirements":[["Прочитай `message`.","Зчитай `message`.","Read `message`."],["Примени `.lower()` и сохрани новый текст в `small`. Пробелы эта операция не удаляет.","Застосуй `.lower()` й збережи новий текст у `small`. Пробіли ця операція не видаляє.","Apply `.lower()` and store the new text in `small`. This operation does not remove spaces."],["Выведи small. В этом задании не используй strip(): пробелы должны остаться.","Виведи small. У цьому завданні не використовуй strip(): пробіли мають залишитися.","Print small. Do not use strip() here: spaces must remain."]],"input":["Одна строка текста.","Один рядок тексту.","One text line."],"starter":"message = input()\n\n","cases":[{"input":["HELLO"],"out":"hello"},{"input":["PyThOn"],"out":"python"},{"input":["  YES  "],"out":"  yes  "},{"input":["TWO Words"],"out":"two words"},{"input":["123"],"out":"123"},{"input":["ПрИвЕт"],"out":"привет"}],"hints":[["PyThOn станет python. Числа и пробелы не меняются.","PyThOn стане python. Числа й пробіли не змінюються.","PyThOn becomes python. Digits and spaces stay unchanged."],["lower() нужно вызвать у переменной с исходным текстом, затем сохранить результат.","lower() потрібно викликати у змінної з початковим текстом, потім зберегти результат.","Call lower() on the variable containing the original text, then store the result."],["Новый текст находится в small. Именно это значение нужно передать print().","Новий текст міститься у small. Саме це значення потрібно передати print().","The new text is stored in small. Pass that value to print()."]],"time":"3–7","revision":1,"preparation":{"topic":"clean-text","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"normalize-word","module":1,"title":["Две операции с текстом","Дві операції з текстом","Two text operations"],"intro":["Соединим уже знакомые strip() и lower(). Пока без условий.","Поєднаймо вже знайомі strip() та lower(). Поки без умов.","Combine the familiar strip() and lower(). No conditions yet."],"requirements":[["Прочитай `word`. Сначала убери пробелы по краям и сохрани текст в `clean`.","Зчитай `word`. Спершу прибери пробіли по краях і збережи текст у `clean`.","Read `word`. First strip edge spaces and store the text in `clean`."],["Затем переведи сохранённое clean в маленькие буквы и сохрани результат снова в clean. Можно делать операции на двух отдельных строках.","Потім переведи збережене clean у малі літери й збережи результат знову у clean. Можна виконувати операції у двох окремих рядках.","Then lowercase the stored clean and store the result back in clean. You may use two separate statements."],["Выведи обработанный текст. Пробелы между словами сохраняются.","Виведи оброблений текст. Пробіли між словами зберігаються.","Print the prepared text. Internal spaces remain."]],"input":["Одна строка текста.","Один рядок тексту.","One text line."],"starter":"word = input()\n\n","cases":[{"input":["  PyThOn  "],"out":"python"},{"input":["HELLO"],"out":"hello"},{"input":["  TWO WORDS "],"out":"two words"},{"input":[" ready "],"out":"ready"},{"input":["   "],"out":""},{"input":[" 123 "],"out":"123"}],"hints":[["Проследи три состояния: «  PyThOn  » → «PyThOn» → «python».","Простеж три стани: «  PyThOn  » → «PyThOn» → «python».","Trace three states: “  PyThOn  ” → “PyThOn” → “python”."],["Вторая операция читает уже обработанный результат первой, а не исходный word.","Друга операція читає вже оброблений результат першої, а не початкове word.","The second operation uses the first operation’s result rather than the original word."],["Чтобы заменить clean, сохрани новое значение под тем же именем через =.","Щоб замінити clean, збережи нове значення під тією самою назвою через =.","To update clean, store the new value under the same name with =."]],"time":"3–7","revision":1,"preparation":{"topic":"clean-text","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"empty-message","module":1,"title":["После пробелов ничего нет","Після пробілів нічого немає","Nothing after trimming"],"intro":["Добавим одну проверку к знакомому strip(): остался ли хоть какой-нибудь текст?","Додаймо одну перевірку до знайомого strip(): чи залишився хоч якийсь текст?","Add one test to strip(): does any text remain?"],"requirements":[["Прочитай `message`. Убери пробелы по краям и сохрани результат в `clean`.","Зчитай `message`. Прибери пробіли по краях і збережи результат у `clean`.","Read `message`. Strip edge spaces and store the result in `clean`."],["Пустая строка записывается как `\"\"`: между кавычками ничего нет. Если clean равен пустой строке, выведи «Пусто». Иначе выведи «Есть текст».","Порожній рядок записується як `\"\"`: між лапками нічого немає. Якщо clean дорівнює порожньому рядку, виведи «Порожньо». Інакше виведи «Є текст».","An empty string is written as `\"\"`, with nothing between quotes. If clean equals the empty string, print “Empty”. Otherwise print “Has text”."]],"input":["Одна строка текста.","Один рядок тексту.","One text line."],"starter":"message = input()\n\n","cases":[{"input":["   "],"out":["Пусто","Порожньо","Empty"]},{"input":[" hello "],"out":["Есть текст","Є текст","Has text"]},{"input":[""],"out":["Пусто","Порожньо","Empty"]},{"input":["0"],"out":["Есть текст","Є текст","Has text"]},{"input":[" x "],"out":["Есть текст","Є текст","Has text"]},{"input":["TWO WORDS"],"out":["Есть текст","Є текст","Has text"]}],"hints":[["Строка из одних пробелов после strip() становится пустой.","Рядок лише з пробілів після strip() стає порожнім.","A spaces-only string becomes empty after strip()."],["Сравни обработанную строку с двумя кавычками подряд: это значение пустого текста.","Порівняй оброблений рядок із двома лапками поспіль: це значення порожнього тексту.","Compare the prepared string with two consecutive quotes, the empty-text value."],["Здесь достаточно одного if и его else. Каждая ветка печатает свой текст.","Тут достатньо одного if та його else. Кожна гілка друкує свій текст.","One if and its else are enough. Each branch prints its own text."]],"time":"3–7","revision":1,"preparation":{"topic":"clean-text","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"age-check","module":2,"title":["Сохранить одну проверку","Зберегти одну перевірку","Store one comparison"],"intro":["Начнём без if: результат сравнения можно сохранить как обычное значение.","Почнімо без if: результат порівняння можна зберегти як звичайне значення.","Start without if: store a comparison result like any other value."],"requirements":[["Прочитай `age`. Проверь, что возраст не меньше 18. Число 18 тоже подходит.","Зчитай `age`. Перевір, що вік не менший за 18. Число 18 теж підходить.","Read `age`. Test whether it is at least 18. Exactly 18 qualifies."],["Сохрани результат сравнения в `adult` через =. Проверка age >= 18 сама даёт True или False, поэтому здесь не нужен блок if.","Збережи результат порівняння у `adult` через =. Перевірка age >= 18 сама дає True або False, тому тут не потрібен блок if.","Store the comparison result in `adult` using =. The test age >= 18 already produces True or False, so no if block is needed."],["Выведи adult. Ответы True и False не переводятся.","Виведи adult. Відповіді True та False не перекладаються.","Print adult. True and False are never translated."]],"input":["Одно целое число: возраст от 0 до 120.","Одне ціле число: вік від 0 до 120.","One integer: age from 0 to 120."],"starter":"age = int(input())\n\n","cases":[{"input":["18"],"out":"True"},{"input":["17"],"out":"False"},{"input":["0"],"out":"False"},{"input":["19"],"out":"True"},{"input":["120"],"out":"True"}],"hints":[["Сначала сравни возраст с 18. Сравнение отвечает «да» или «нет», а не возвращает сам возраст.","Спершу порівняй вік із 18. Порівняння відповідає «так» або «ні», а не повертає сам вік.","The comparison answers yes or no rather than returning the age."],["Форма присваивания: имя = проверка. Двоеточие и отступ для такого сохранения не нужны.","Форма присвоєння: назва = перевірка. Двокрапка й відступ для такого збереження не потрібні.","The assignment shape is name = comparison. No colon or indentation is needed."],["True и False — значения Python. При выводе переменной не заключай её имя в кавычки.","True та False — значення Python. Під час виводу змінної не бери її назву в лапки.","True and False are Python values. Do not quote the variable name when printing it."]],"time":"3–7","revision":1,"preparation":{"topic":"saved-conditions","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"pass-check","module":2,"title":["Сохранить проверку текста","Зберегти перевірку тексту","Store a text comparison"],"intro":["Повторим тот же приём со строкой: совпал ли ответ с нужным словом?","Повторімо той самий прийом із рядком: чи збіглася відповідь із потрібним словом?","Practise the same technique with text: does the answer match the required word?"],"requirements":[["Прочитай `answer`. Во вводе «да» или «нет».","Зчитай `answer`. У вводі «так» або «ні».","Read `answer`, either “yes” or “no”."],["Сохрани в `has_pass` результат сравнения answer с текстом «да». Для сравнения используют ==, слово пишут в кавычках.","Збережи у `has_pass` результат порівняння answer з текстом «так». Для порівняння використовують ==, слово пишуть у лапках.","Store in `has_pass` whether answer equals the text “yes”. Use == to compare, with the word in quotes."],["Выведи только has_pass: True или False.","Виведи лише has_pass: True або False.","Print only has_pass: True or False."]],"input":["Одна строка: да или нет.","Один рядок: так або ні.","One line: yes or no."],"starter":"answer = input()\n\n","cases":[{"input":[["да","так","yes"]],"out":"True"},{"input":[["нет","ні","no"]],"out":"False"}],"hints":[["Для «да» проверка верна, для «нет» неверна.","Для «так» перевірка істинна, для «ні» хибна.","The comparison is true for “yes” and false for “no”."],["Слева от = стоит имя has_pass. Справа — полное сравнение строки через ==.","Ліворуч від = стоїть назва has_pass. Праворуч — повне порівняння рядка через ==.","Put has_pass left of = and the complete text comparison right of it."],["True и False — значения Python. При выводе переменной не заключай её имя в кавычки.","True та False — значення Python. Під час виводу змінної не бери її назву в лапки.","True and False are Python values. Do not quote the variable name when printing it."]],"time":"3–7","revision":1,"preparation":{"topic":"saved-conditions","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"invert-flag","module":2,"title":["Противоположный ответ","Протилежна відповідь","The opposite answer"],"intro":["Добавим только not: он превращает True в False, а False в True.","Додаймо лише not: він перетворює True на False, а False на True.","Add only not: it turns True into False and False into True."],"requirements":[["Прочитай `age`. Сохрани проверку age >= 18 в `adult`, как в первой задаче темы.","Зчитай `age`. Збережи перевірку age >= 18 у `adult`, як у першому завданні теми.","Read `age`. Store age >= 18 in `adult` as in this topic’s first exercise."],["Сохрани противоположный ответ в `child`: поставь `not` перед именем adult. Это означает «не взрослый».","Збережи протилежну відповідь у `child`: постав `not` перед назвою adult. Це означає «не дорослий».","Store the opposite answer in `child` by placing `not` before adult. It means “not an adult”."],["Выведи child. Для 17 ожидается True, для 18 — False.","Виведи child. Для 17 очікується True, для 18 — False.","Print child. Age 17 gives True; age 18 gives False."]],"input":["Одно целое число: возраст от 0 до 120.","Одне ціле число: вік від 0 до 120.","One integer: age from 0 to 120."],"starter":"age = int(input())\n\n","cases":[{"input":["17"],"out":"True"},{"input":["18"],"out":"False"},{"input":["0"],"out":"True"},{"input":["120"],"out":"False"},{"input":["19"],"out":"False"}],"hints":[["Проследи два ответа: adult для 17 равен False. Противоположный ответ равен True.","Простеж дві відповіді: adult для 17 дорівнює False. Протилежна відповідь дорівнює True.","At age 17 adult is False, so the opposite answer is True."],["not ставят перед готовым логическим значением. Он не меняет число age.","not ставлять перед готовим логічним значенням. Він не змінює число age.","Put not before an existing Boolean value. It does not change age."],["True и False — значения Python. При выводе переменной не заключай её имя в кавычки.","True та False — значення Python. Під час виводу змінної не бери її назву в лапки.","True and False are Python values. Do not quote the variable name when printing it."]],"time":"3–7","revision":1,"preparation":{"topic":"saved-conditions","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"either-door","module":2,"title":["Достаточно одной двери","Достатньо одних дверей","One open door is enough"],"intro":["Потренируем or и выведем только сохранённый ответ, без веток if.","Потренуймо or й виведемо лише збережену відповідь, без гілок if.","Practise or and print the stored answer, without if branches."],"requirements":[["Прочитай `left` и `right` с двух строк. «да» означает, что соответствующая дверь открыта.","Зчитай `left` та `right` із двох рядків. «так» означає, що відповідні двері відчинені.","Read `left` and `right` on separate lines. “yes” means that door is open."],["Выйти можно, если открыта левая или правая дверь. Соедини две полные проверки через `or` и сохрани результат в `can_leave`. Обе открытые двери тоже подходят.","Вийти можна, якщо відчинені ліві або праві двері. Поєднай дві повні перевірки через `or` й збережи результат у `can_leave`. Обидві відчинені двері теж підходять.","You may leave if the left or right door is open. Combine two full comparisons with `or` and store the result in `can_leave`. Both open doors qualify too."],["Выведи can_leave: True или False.","Виведи can_leave: True або False.","Print can_leave: True or False."]],"input":["Две строки: левая дверь и правая дверь, да или нет.","Два рядки: ліві двері й праві двері, так або ні.","Two lines: left and right door, yes or no."],"starter":"left = input()\nright = input()\n\n","cases":[{"input":[["да","так","yes"],["нет","ні","no"]],"out":"True"},{"input":[["нет","ні","no"],["да","так","yes"]],"out":"True"},{"input":[["да","так","yes"],["да","так","yes"]],"out":"True"},{"input":[["нет","ні","no"],["нет","ні","no"]],"out":"False"}],"hints":[["Если обе двери закрыты, ни одна проверка не верна: результат False.","Якщо обидві двері зачинені, жодна перевірка не істинна: результат False.","Both closed means neither comparison is true, so the result is False."],["or требует хотя бы одну верную проверку. and потребовал бы сразу две — это другое правило.","or потребує хоча б одну істинну перевірку. and потребував би одразу дві — це інше правило.","or requires at least one true comparison. and would require both."],["По обе стороны or должно быть сравнение переменной с нужным словом, а не просто слово в кавычках.","З обох боків or має бути порівняння змінної з потрібним словом, а не просто слово в лапках.","Each side of or needs a variable-to-word comparison, not just a quoted word."]],"time":"3–7","revision":1,"preparation":{"topic":"saved-conditions","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"add-fee","module":3,"title":["Увеличить сохранённое число","Збільшити збережене число","Increase a stored number"],"intro":["Начнём с одного изменения переменной. Условие пока не нужно.","Почнімо з однієї зміни змінної. Умова поки не потрібна.","Start with one variable update. No condition is needed yet."],"requirements":[["Прочитай `price` от 0 до 5000. Упаковка всегда добавляет 30 к этой цене.","Зчитай `price` від 0 до 5000. Пакування завжди додає 30 до цієї ціни.","Read `price` from 0 to 5000. Packaging always adds 30."],["Возьми старое значение price, прибавь 30 и сохрани новый результат обратно в price. Справа от = вычисляется новое число, слева указано, куда его сохранить.","Візьми старе значення price, додай 30 й збережи новий результат назад у price. Праворуч від = обчислюється нове число, ліворуч указано, куди його зберегти.","Read the old price, add 30, and store the new result back in price. The right side of = calculates the value; the left side names where to store it."],["После изменения выведи price один раз.","Після зміни виведи price один раз.","After the update, print price once."]],"input":["Одно целое число: исходная цена.","Одне ціле число: початкова ціна.","One integer: original price."],"starter":"price = int(input())\n\n","cases":[{"input":["80"],"out":"110"},{"input":["0"],"out":"30"},{"input":["1"],"out":"31"},{"input":["100"],"out":"130"},{"input":["5000"],"out":"5030"}],"hints":[["Исходная цена 80 должна превратиться в 110. Цена 0 — в 30.","Початкова ціна 80 має перетворитися на 110. Ціна 0 — на 30.","An original price of 80 becomes 110; 0 becomes 30."],["Другой пример: coins = coins + 2 берёт старые coins, прибавляет 2 и сохраняет новый результат.","Інший приклад: coins = coins + 2 бере старі coins, додає 2 й зберігає новий результат.","Another example: coins = coins + 2 reads the old coins, adds 2, and stores the new value."],["Одно только price + 30 не заменяет price. Для сохранения результата нужен знак =.","Саме лише price + 30 не замінює price. Для збереження результату потрібен знак =.","price + 30 alone does not update price. Store the result with =."]],"time":"3–7","revision":1,"preparation":{"topic":"several-actions","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"discount-only","module":3,"title":["Уменьшить сохранённое число","Зменшити збережене число","Decrease a stored number"],"intro":["Повторим сохранение нового значения, теперь с вычитанием.","Повторімо збереження нового значення, тепер із відніманням.","Practise storing an updated value, now using subtraction."],"requirements":[["Прочитай `price` от 40 до 2000. Скидка всегда равна 40.","Зчитай `price` від 40 до 2000. Знижка завжди дорівнює 40.","Read `price` from 40 to 2000. The discount is always 40."],["Вычти 40 из текущей цены и сохрани новый результат в ту же price. Число 40 — размер скидки, а не новая цена.","Відніми 40 від поточної ціни й збережи новий результат у ту саму price. Число 40 — розмір знижки, а не нова ціна.","Subtract 40 from the current price and store the result back in price. 40 is the discount amount, not the new price."],["Выведи изменённую цену. if здесь пока не требуется.","Виведи змінену ціну. if тут поки не потрібен.","Print the updated price. No if is required yet."]],"input":["Одно целое число: исходная цена.","Одне ціле число: початкова ціна.","One integer: original price."],"starter":"price = int(input())\n\n","cases":[{"input":["100"],"out":"60"},{"input":["40"],"out":"0"},{"input":["41"],"out":"1"},{"input":["150"],"out":"110"},{"input":["2000"],"out":"1960"}],"hints":[["От цены 100 после скидки 40 остаётся 60.","Від ціни 100 після знижки 40 залишається 60.","A price of 100 minus a discount of 40 leaves 60."],["Справа от = должны быть старое значение и вычитание. Слева остаётся имя price.","Праворуч від = мають бути старе значення й віднімання. Ліворуч залишається назва price.","Put the old value and subtraction right of =; keep price on the left."],["Сначала обнови цену, затем печатай её. Ранний print покажет старую цену.","Спершу онови ціну, потім друкуй її. Ранній print покаже стару ціну.","Update first, print second. Printing too early shows the old price."]],"time":"3–7","revision":1,"preparation":{"topic":"several-actions","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"member-price","module":3,"title":["Скидка по условию","Знижка за умовою","A conditional discount"],"intro":["Добавим знакомый if к уже отработанному вычитанию.","Додаймо знайомий if до вже відпрацьованого віднімання.","Add a familiar if to the subtraction you have practised."],"requirements":[["Прочитай `price` от 40 до 2000, затем `member`: «да» или «нет». Обе строки есть всегда.","Зчитай `price` від 40 до 2000, потім `member`: «так» або «ні». Обидва рядки є завжди.","Read `price` from 40 to 2000, then `member`: “yes” or “no”. Both inputs are present."],["Только если member равен «да» вычти 40 из price и сохрани изменённую цену. При «нет» ничего не меняй.","Лише якщо member дорівнює «так» відніми 40 від price й збережи змінену ціну. Для «ні» нічого не змінюй.","Only when member is “yes”, subtract 40 and store the updated price. For “no”, leave it unchanged."],["Выведи price один раз после проверки, без отступа. Так результат будет и со скидкой, и без неё.","Виведи price один раз після перевірки, без відступу. Так результат буде і зі знижкою, і без неї.","Print price once after the condition, without indentation. This prints a result with or without a discount."]],"input":["Две строки: цена, затем наличие карты.","Два рядки: ціна, потім наявність картки.","Two lines: price, then membership."],"starter":"price = int(input())\nmember = input()\n\n","cases":[{"input":["100",["да","так","yes"]],"out":"60"},{"input":["100",["нет","ні","no"]],"out":"100"},{"input":["40",["да","так","yes"]],"out":"0"},{"input":["40",["нет","ні","no"]],"out":"40"},{"input":["2000",["да","так","yes"]],"out":"1960"},{"input":["2000",["нет","ні","no"]],"out":"2000"}],"hints":[["Сначала реши, нужна ли скидка. Само изменение цены ты уже делал в предыдущей задаче.","Спершу виріши, чи потрібна знижка. Саму зміну ціни ти вже робив у попередньому завданні.","First decide whether a discount applies. You already practised the price update."],["Условие сравнивает member с нужным словом через ==. После двоеточия изменение цены пишется с отступом.","Умова порівнює member із потрібним словом через ==. Після двокрапки зміну ціни пишуть із відступом.","Compare member with the required word using ==. Indent the price update under the condition."],["print с отступом внутри if пропустит вывод при «нет». Итог печатай после блока на общем уровне.","print із відступом усередині if пропустить вивід для «ні». Підсумок друкуй після блоку на загальному рівні.","Printing inside if would skip the “no” case. Print after the block at the outer level."]],"time":"3–7","revision":1,"preparation":{"topic":"several-actions","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}},{"id":"two-adjustments","module":3,"title":["Скидка и упаковка","Знижка й пакування","Discount and packaging"],"intro":["Теперь два независимых изменения одной цены. Оба правила могут сработать вместе.","Тепер дві незалежні зміни однієї ціни. Обидва правила можуть спрацювати разом.","Now update one price using two independent rules. Both may apply."],"requirements":[["Прочитай `price` от 40 до 2000, затем `member` и `wrap`: «да» или «нет». Все три строки есть всегда.","Зчитай `price` від 40 до 2000, потім `member` та `wrap`: «так» або «ні». Усі три рядки є завжди.","Read `price` from 40 to 2000, then `member` and `wrap`: “yes” or “no”. All three lines are present."],["Если member равен «да», уменьши price на 40. Затем отдельно проверь wrap: при «да» увеличь текущую price на 15.","Якщо member дорівнює «так», зменш price на 40. Потім окремо перевір wrap: для «так» збільш поточну price на 15.","If member is “yes”, subtract 40. Then separately check wrap: if “yes”, add 15 to the current price."],["Это два самостоятельных if на одном уровне, потому что скидка и упаковка могут быть одновременно. После обоих изменений выведи только итоговую price.","Це два самостійні if на одному рівні, бо знижка й пакування можуть бути одночасно. Після обох змін виведи лише підсумкову price.","Use two independent if statements at the same level: discount and packaging can both apply. After both updates, print only the final price."]],"input":["Три строки: цена, карта, упаковка.","Три рядки: ціна, картка, пакування.","Three lines: price, membership, packaging."],"starter":"price = int(input())\nmember = input()\nwrap = input()\n\n","cases":[{"input":["100",["да","так","yes"],["да","так","yes"]],"out":"75"},{"input":["100",["да","так","yes"],["нет","ні","no"]],"out":"60"},{"input":["100",["нет","ні","no"],["да","так","yes"]],"out":"115"},{"input":["100",["нет","ні","no"],["нет","ні","no"]],"out":"100"},{"input":["40",["да","так","yes"],["да","так","yes"]],"out":"15"},{"input":["40",["да","так","yes"],["нет","ні","no"]],"out":"0"},{"input":["2000",["нет","ні","no"],["да","так","yes"]],"out":"2015"}],"hints":[["Для 100 с картой и упаковкой: 100 → 60 → 75. Второй шаг использует уже изменённую цену.","Для 100 з карткою й пакуванням: 100 → 60 → 75. Другий крок використовує вже змінену ціну.","For 100 with membership and packaging: 100 → 60 → 75. The second update uses the changed price."],["elif пропустил бы второе правило, если первое сработало. Здесь нужен новый отдельный if.","elif пропустив би друге правило, якби перше спрацювало. Тут потрібен новий окремий if.","elif would skip the second rule when the first matched. Start another independent if here."],["Каждое правило сохраняет результат обратно в price. print стоит после обоих блоков без отступа.","Кожне правило зберігає результат назад у price. print стоїть після обох блоків без відступу.","Store each updated result back in price. Print after both blocks, without indentation."]],"time":"3–7","revision":1,"preparation":{"topic":"several-actions","text":["Разобрать приём на другом примере","Розібрати прийом на іншому прикладі","Learn the technique using another example"]}}];
