Object.assign(UI,{practiceStep:["Задача {n} из 6 · {tier}", "Завдання {n} із 6 · {tier}", "Exercise {n} of 6 · {tier}"],practiceTiers:[["Первый приём", "Перший прийом", "One technique"], ["Закрепляем", "Закріплюємо", "Build confidence"], ["Соединяем приёмы", "Поєднуємо прийоми", "Combine techniques"]]});
